    /**
     * Canada Post Shipping Provider class.
     *
     * Provides Canada Post tracking number validation, supported countries, and tracking URL generation.
     */
    class CanadaPostShippingProvider extends \Automattic\WooCommerce\Admin\Features\Fulfillments\Providers\AbstractShippingProvider
    {
        /**
         * Canada Post tracking number patterns with service differentiation.
         *
         * @var array<string, array{patterns: array<int, string>, confidence: int}>
         */
        private const TRACKING_PATTERNS = array('CA' => array(
            // Canada.
            'patterns' => array(
                // UPU S10 international format (outbound).
                '/^[A-Z]{2}\d{9}CA$/',
                // Standard format: XX#########CA.
                // UPU S10 international (inbound/other countries, fallback).
                '/^[A-Z]{2}\d{9}[A-Z]{2}$/',
                // Any S10/UPU code.
                // Domestic numeric formats.
                '/^\d{16}$/',
                // 16-digit domestic tracking.
                '/^\d{15}$/',
                // 15-digit legacy/partner/returns.
                '/^\d{14}$/',
                // 14-digit legacy/partner/returns.
                '/^\d{13}$/',
                // 13-digit domestic (most common).
                '/^\d{12}$/',
                // 12-digit domestic.
                '/^\d{10}$/',
                // 10-digit legacy.
                '/^\d{9}$/',
                // 9-digit legacy.
                '/^\d{8}$/',
                // 8-digit calling card/legacy.
                // Service-specific patterns.
                '/^XP\d{9}CA$/',
                // Xpresspost International.
                '/^EX\d{9}CA$/',
                // Express International.
                '/^PR\d{9}CA$/',
                // Priority.
                '/^RG\d{9}CA$/',
                // Regular (deprecated, legacy).
                '/^RM\d{9}CA$/',
                // Registered Mail.
                '/^CM\d{9}CA$/',
                // Certified Mail.
                '/^[A-Z]{2}\d{7}[A-Z]{2}$/',
                // International format: XX#######XX.
                '/^[A-Z]{1}\d{9}[A-Z]{1}$/',
                // Domestic formats: X#########X.
                '/^FD\d{10,12}$/',
                // FlexDelivery.
                '/^PO\d{10,12}$/',
                // Post Office Box service.
                '/^CP\d{10,14}$/',
                // Canada Post business.
                '/^SM\d{10,14}$/',
                // Small packet.
                // Legacy and alternative formats.
                '/^[0-9]{13}[A-Z]{1}$/',
            ),
            'confidence' => 92,
        ));
        /**
         * Get the unique key for this shipping provider.
         *
         * @return string Unique key.
         */
        public function get_key(): string
        {
