         *         if ( $processor->opens_block( 'core/code', 'syntaxhighlighter/code' ) ) {
         *             echo "Found code!";
         *             continue;
         *         }
         *
         *         if ( $processor->opens_block( 'core/image' ) ) {
         *             echo "Found an image!";
         *             continue;
         *         }
